import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/festivals/naga-panchami/',[('','Nāga Pañcamī','The Serpents’ Fifth Day')],'navy','Nāga Pañcamī','Lord','Nāga Pañcamī')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/naga-panchami/'
i=0
def cobra(c='#2a6a3a'): return f'<path d="M-6 0 q-14 -20 0 -40 q10 -14 0 -30" fill="none" stroke="{c}" stroke-width="9"/><path d="M-14 -74 q14 -30 28 0 q-14 10 -28 0z" fill="{c}"/><circle cx="-4" cy="-76" r="1.6" fill="#ffd60a"/><circle cx="4" cy="-76" r="1.6" fill="#ffd60a"/>'
def nagakallu(): return '<path d="M-26 0 v-60 q26 -24 52 0 v60z" fill="#8a8f9a"/>'+g(0,-8,.6,cobra('#5a5f6a'))
def anthill(): return '<path d="M-40 0 q10 -30 20 -40 q8 -26 20 -30 q12 4 20 30 q10 10 20 40z" fill="#b5651d"/><circle cx="0" cy="-30" r="5" fill="#3a2a1a"/><circle cx="-14" cy="-14" r="4" fill="#3a2a1a"/>'
def garuda(): return g(0,0,1.6,bird('#c0582a'))
def grove(): return ''.join(g(x,0,.8,tree('#2f6a3a')) for x in (-40,0,40))+g(0,0,.6,nagakallu())
def milkpot(): return pot('#fff8e7')
def mandala(): return ''.join(f'<path d="M{20*__import__("math").cos(k*0.785):.1f} {20*__import__("math").sin(k*0.785):.1f} q{30*__import__("math").cos(k*0.785+0.5):.1f} {30*__import__("math").sin(k*0.785+0.5):.1f} {50*__import__("math").cos(k*0.785):.1f} {50*__import__("math").sin(k*0.785):.1f}" fill="none" stroke="{c}" stroke-width="4"/>' for k,c in enumerate(['#c0392b','#e0a800','#2a9d6f','#1d6fb8']*2))+'<circle r="12" fill="#e0a800"/>'
COV=covart('Women pouring milk on a serpent stone under a tree beside an anthill, in monsoon rain',f'<rect width="440" height="196" fill="#cfe0d8"/>'+''.join(f'<path d="M{x} {y} l-4 12" stroke="#8fb8de" stroke-width="2"/>' for x,y in [(40,20),(90,40),(150,10),(300,30),(360,15),(410,45),(250,8)])+'<rect y="160" width="440" height="36" fill="#a8c890"/>'+g(220,186,1.3,tree('#2f6a3a'))+g(220,188,1.5,nagakallu())+g(350,188,1.1,anthill())+g(120,188,1.1,person('#c0392b'))+g(150,150,.8,milkpot()))
pp=[foreword(i,['On the fifth day of the bright fortnight of Śrāvaṇa, with the monsoon in full flow, Karnataka’s women go out to the <b>huttu</b> (anthills) and <b>nāgara kallu</b> (serpent stones) under village trees, and pour milk. This is <b>Nāgara Pañcamī</b>, the first of the long run of festivals from Śrāvaṇa to Dīpāvali, and above all a festival of sisters praying for their brothers.','Snakes come out with the rains, and the festival turns fear into worship. This article tells the stories behind it from the Mahābhārata (Kadru’s curse, Takṣaka and Parīkṣit, Janamejaya’s snake sacrifice stopped by the boy Āstīka) and the Bhāgavata (Kṛṣṇa and Kāliya), gives the nine-nāga verse, and goes from Karnataka’s homes to the sacred groves of Tuḷunāḍu and Kukke Subrahmaṇya, with a frank page on being kind to real snakes.'],[('z','Why worship snakes?'),('b','Because we share the land with them, Zappy. The festival says: respect, don’t kill. And it’s much older than any one story.')]),
 glance([('Name','Nāga Pañcamī; Nāgara Pañcamī (Karnataka); Nāgula Chavithi in the Telugu states (Kārtika)'),('When','Śrāvaṇa Śukla Pañcamī (July–August); in parts of the north, Kṛṣṇa Pañcamī'),('Day before','Nāgara Cauti, a fast in many Karnataka homes'),('Worship','Milk, turmeric, kuṅkuma, flowers and cotton garlands on serpent stones and anthills'),('Stories','Kadru and Vinatā; Takṣaka and Parīkṣit; Āstīka stops Janamejaya’s snake sacrifice; Kāliya'),('Texts','Mahābhārata, Ādi Parvan (Āstīka Parvan); Bhāgavata 10.16; Garuḍa, Skanda, Nārada Purāṇas'),('Karnataka','Sisters and brothers; tambiṭṭu, eḷḷuṇḍe, arisina ele kaḍubu; nāgabanas; Kukke Subrahmaṇya')],svg(560,140,'A serpent stone, an anthill and a pot of milk',f'<rect width="560" height="140" fill="#cfe0d8"/>'+'<rect y="118" width="560" height="22" fill="#a8c890"/>'+g(180,130,1.3,nagakallu())+g(330,130,1,anthill())+g(450,130,1.2,milkpot()))),
 reading('rains','THE MONSOON AND THE SERPENTS','Why this festival, why now',svg(560,160,'Rain falling on fields with a cobra leaving a flooded hole',f'<rect width="560" height="160" fill="#cfe0d8"/>'+''.join(f'<path d="M{x} {y} l-5 14" stroke="#5a8ab8" stroke-width="2"/>' for x in range(20,560,40) for y in (20,60))+'<rect y="120" width="560" height="40" fill="#a8c890"/>'+g(280,130,1,anthill())+g(340,128,.9,cobra())),['<b>The rains.</b> In Śrāvaṇa the monsoon fills the burrows, and snakes come out into fields, courtyards and homes. Snakebite was a real danger for farming families; the festival asks for protection and peace.','<b>The earth.</b> Nāgas are spirits of the earth and the water beneath it, guardians of springs, wells and treasure. On this day many families do not dig, plough, cut or fry, so as not to hurt anything living in the ground.','<b>The first festival.</b> In Karnataka, Nāgara Pañcamī opens the festival season: Varamahālakṣmī, Janmāṣṭamī, Gaurī-Gaṇeśa, Navarātri and Dīpāvali follow. Old people call it <i>habbagaḷa tavaru</i>, the mother’s home of festivals.','<b>Very old.</b> Serpent worship in India is older than any surviving text; stones with snakes carved on them stand under village trees across the south, often beside a pīpal and a neem planted together.'],[('z','So it’s about the rains as much as the snakes?'),('b','They come together, Zappy. The festival is the village making peace with both.')],'Rain brings <b>the serpents out</b>.'),
 story('kadru','KADRU, VINATĀ AND THE CURSE','Where the nāgas come from',strip('Three panels: two sisters arguing about the colour of a white horse’s tail; black serpents hanging on the tail to darken it; Kadru cursing her sons to burn in a sacrifice',[panel([(person('#2a6a3a'),.9),(person('#e0a800'),.9),(beast('donkey','#fff'),.6)],'#fff3cf',150),panel([(beast('donkey','#fff'),.8),(cobra('#222'),.5)],'#dfe9f6',150),panel([(person('#2a6a3a'),1),(fire(),.7)],'#fde4e4',150)],['the bet','the trick','the mother’s curse']),'Mahābhārata, Ādi Parvan, Āstīka Parvan (chs. 14–30 in common editions).',['The sage Kaśyapa had two wives, <b>Kadru</b> and <b>Vinatā</b>. Kadru bore a thousand serpent sons, the <b>nāgas</b>; Vinatā bore two sons, Aruṇa and later <b>Garuḍa</b>.','The sisters made a bet on the colour of the tail of the white horse Uccaiḥśravas: the loser would be the winner’s slave. Vinatā said white; Kadru said black.','Kadru told her sons to hang on the tail and make it look black. Those who refused she cursed: they would burn in a king’s fire sacrifice.','Vinatā lost by the trick and became Kadru’s slave, until Garuḍa won her freedom by bringing the nectar of immortality from heaven. Ever since, Garuḍa and the serpents are enemies.','The mother’s curse waited for its time: a snake sacrifice of King Janamejaya, many generations later.'],[('z','A mother cursed her own children?'),('b','For refusing to cheat, Zappy. The Mahābhārata never hides how strange its families are.')],'A curse that <b>waits for its time</b>.'),
 story('parikshit','TAKṢAKA AND PARĪKṢIT','The bite that started it all',strip('Three panels: King Parīkṣit placing a dead snake on a meditating sage’s shoulders; the sage’s son cursing him; Takṣaka hidden in a fruit, biting the king',[panel([(god('#7a3fa0'),.9),(sage('#ff8c1a'),.9),(cobra('#222'),.4)],'#e9e3f5',150),panel([(child(),1),(sage('#ff8c1a'),.7)],'#fde4e4',150),panel([(god('#7a3fa0'),.9),(cobra(),.6)],'#fff3cf',150)],['the insult','the curse','Takṣaka strikes']),'Mahābhārata, Ādi Parvan; the Bhāgavata’s frame story (book 1 and 12).',['King <b>Parīkṣit</b>, Arjuna’s grandson, thirsty after a hunt, asked a sage in meditation for water. The sage did not answer. In anger the king hung a dead snake round his neck.','The sage’s son, Śṛṅgī, cursed the king: within seven days <b>Takṣaka</b>, king of serpents, would bite him and he would die.','Parīkṣit accepted the curse. In the Bhāgavata he spends the seven days listening to Śuka tell the whole Bhāgavata Purāṇa.','Takṣaka came disguised, hid as a worm in a fruit offered to the king, and bit him; Parīkṣit died.','His son <b>Janamejaya</b> grew up and swore revenge on all serpents.'],[('z','The Bhāgavata was told because of a snake?'),('b','In a way, Zappy. A king with seven days to live asked the best question of his life.')],'Seven days and <b>a fruit</b>.'),
 story('astika','ĀSTĪKA STOPS THE SACRIFICE','Why the fifth day is the serpents’',strip('Three panels: Janamejaya’s fire sacrifice with serpents falling in; the boy sage Āstīka arriving and praising the king; the sacrifice stopped and Takṣaka saved',[panel([(god('#e0a800'),.8),(fire(),.9),(cobra(),.4)],'#fde4e4',150),panel([(child(),1),(god('#e0a800'),.8)],'#fff3cf',150),panel([(cobra(),.7),(child(),.8)],'#e3f5e9',150)],['the snake sacrifice','the boy’s request','the serpents saved']),'Mahābhārata, Ādi Parvan, Āstīka Parvan.',['Janamejaya held the <b>sarpa-satra</b>, the serpent sacrifice. By the priests’ mantras, snakes from every land were dragged through the air and fell into the fire by the thousand. Kadru’s curse was coming true.','<b>Āstīka</b>, a boy-sage whose mother was the nāga princess Jaratkāru, sister of Vāsuki, set out to save his mother’s people.','At the sacrifice he praised the king, the priests and the fire so beautifully that Janamejaya offered him any boon.','Āstīka asked one thing: stop the sacrifice. The king was bound by his word; the fire was put out, and <b>Takṣaka</b>, already falling, was saved in mid-air.','Tradition holds that the sacrifice stopped on Śrāvaṇa Śukla Pañcamī, and the serpents promised to spare anyone who remembers Āstīka. Hence Nāga Pañcamī.'],[('z','A boy stopped a king’s sacrifice?'),('b','With kind words and a promise, Zappy. Āstīka is the festival’s real hero.')],'Kind words <b>put out the fire</b>.'),
 verse('v-nava','Nava Nāga Stotra','The nine great serpents',['anantaṃ vāsukiṃ śeṣaṃ padmanābhaṃ ca kambalam','śaṅkhapālaṃ dhārtarāṣṭraṃ takṣakaṃ kāliyaṃ tathā','etāni nava nāmāni nāgānāṃ ca mahātmanām','sāyaṅkāle paṭhen nityaṃ prātaḥkāle viśeṣataḥ','tasya viṣabhayaṃ nāsti sarvatra vijayī bhavet'],svg(200,150,'Nine small cobras in a semicircle',f'<rect width="200" height="150" fill="#cfe0d8"/>'+''.join(g(100+80*__import__("math").cos(3.14+k*0.39),130+60*__import__("math").sin(3.14+k*0.39),.45,cobra()) for k in range(9))),'Ananta, Vāsuki, Śeṣa, Padmanābha and Kambala, Śaṅkhapāla, Dhārtarāṣṭra, Takṣaka and Kāliya: these are the nine names of the great serpents. Whoever recites them every evening, and especially in the morning, has no fear of poison and is victorious everywhere.',[('anantam','Ananta, the endless'),('vāsukim','Vāsuki, Śiva’s serpent'),('śeṣam','Śeṣa, Viṣṇu’s couch'),('takṣakam','Takṣaka'),('viṣa-bhayam','fear of poison'),('vijayī','victorious')],'<b>A roll-call of serpents.</b> The nine names include the cosmic serpents (Ananta and Śeṣa, on whom Viṣṇu rests; Vāsuki, the churning rope and Śiva’s necklace), the villain of the Mahābhārata (Takṣaka) and the one Kṛṣṇa tamed (Kāliya). It is the verse most often said on Nāga Pañcamī.',k='Nine names <b>against fear</b>.',note='Text as on shlokam.org (Anantam Vasukim Sesham) and sanskritdocuments.org (Navanāganāmastotram), normalised to IAST; editions differ slightly.'),
 story('kaliya','KṚṢṆA AND KĀLIYA','The dance on the serpent’s hoods',strip('Three panels: the poisoned Yamunā pool with dead cows; Kṛṣṇa diving in and caught in the serpent’s coils; Kṛṣṇa dancing on Kāliya’s hoods while the serpent’s wives pray',[panel([(river(144,110,'#3a6a3a'),1),(cow(),.5)],'#cfe0d8',None),panel([(cobra('#1a3a2a'),.9),(krishna_child(),.6)],'#3a6a5a',150),panel([(cobra('#1a3a2a'),.8),(krishna_child(),.6)],'#dfe9f6',150)],['the poisoned pool','caught in the coils','the dance']),'Bhāgavata Purāṇa 10.16.',['The great serpent <b>Kāliya</b> had made a pool of the Yamunā his home, and its water was so poisonous that birds flying over it fell dead and the cowherd boys’ cattle died drinking from it.','Little <b>Kṛṣṇa</b> climbed a kadamba tree on the bank and dived in. Kāliya wrapped him in his coils, and all Vraja wept on the shore.','Kṛṣṇa slipped free, leapt onto the serpent’s many hoods and danced on them, stamping down each hood that rose, until Kāliya vomited blood and gave up.','Kāliya’s wives, the nāga-patnīs, prayed to Kṛṣṇa to spare their husband. Kṛṣṇa forgave him and sent him to the ocean island Ramaṇaka, promising that Garuḍa would not harm him, since he bore Kṛṣṇa’s footprints on his head.','The river was clean again. The story shows the festival’s balance: the dangerous serpent is subdued, not destroyed.'],[('z','Kṛṣṇa forgave him?'),('b','Because his wives asked, Zappy. Even the serpent who poisoned the river is spared.')],'Subdued, <b>not destroyed</b>.'),
 reading('karnataka','NĀGARA PAÑCAMĪ IN KARNATAKA','Sisters, milk and serpent stones',svg(560,170,'A sister pouring milk on a serpent stone and an anthill while her brother watches; turmeric threads',f'<rect width="560" height="170" fill="#cfe0d8"/>'+'<rect y="140" width="560" height="30" fill="#a8c890"/>'+g(160,150,1.3,nagakallu())+g(260,150,1.1,person('#c0392b'))+g(330,150,1,god('#2a5aa8'))+g(450,150,1.1,anthill())+g(250,100,.7,milkpot())),['<b>The day before.</b> Many keep <b>Nāgara Cauti</b> on the fourth as a fast; on the fifth morning women and girls in new clothes carry milk, turmeric, kuṅkuma, flowers and cotton garlands (<i>gejje vastra</i>) to the village nāgara kallu or an anthill.','<b>Milk for the brothers.</b> The heart of the Kannada festival is the brother. Sisters pour milk on the stone or anthill and pray for their brothers’ long life; in many places the sister then touches the milk to her brother’s back and eyes, and he gives her a gift. The custom is called <b>tani ereyuvudu</b> or tanihālu in many districts.','<b>Daughters come home.</b> In north Karnataka newly married daughters return to their parents’ home for Pañcamī; swings are hung from trees for the girls and songs of the season are sung. Girls tie turmeric-dipped threads and draw serpent designs in rangoli.','<b>No harm.</b> Many families do not cut vegetables, fry or dig on Pañcamī, so as not to injure any creature; food is steamed or prepared the day before.'],[('z','The sister pours milk for the brother?'),('b','Rakṣā Bandhan has a thread, Zappy; Karnataka’s Pañcamī has milk. Same love.')],'Milk <b>for a brother’s life</b>.'),
 story('farmer','THE FARMER’S DAUGHTER','The vrata story told in homes',strip('Three panels: a farmer ploughing and killing baby snakes; the mother serpent taking revenge on the family; the daughter offering milk and the serpent restoring her family',[panel([(person('#6a4a2a'),.9),(cow(),.6)],'#e9d6c0',150),panel([(cobra(),.9),(person('#6a4a2a'),.7)],'#3a3a4a',150),panel([(person('#c0392b'),.9),(milkpot(),.8),(cobra(),.6)],'#fff3cf',150)],['the plough','the revenge','the daughter’s milk']),'A household vrata-kathā; versions differ from district to district.',['A farmer, ploughing his field in Śrāvaṇa, accidentally killed a nest of young snakes.','The mother serpent, wild with grief, took revenge on the farmer’s family, and in the night bit them one by one.','Only a married daughter, living in another village, was spared. The serpent went there too, and found her worshipping a serpent image with milk, it being Nāga Pañcamī.','Moved by her devotion, the serpent drank the milk and was calmed. The daughter begged for her family’s lives, and the serpent gave her a nectar that restored them.','So, the story ends, on Pañcamī one should not plough or dig, and should honour the serpents with milk; and so sisters keep the day for their families.'],[('z','The daughter saved everyone?'),('b','By the festival she kept, Zappy. That’s why it’s the daughters’ and sisters’ day.')],'A daughter’s vow <b>saves the house</b>.'),
 cards('food','PAÑCAMĪ FOOD','Tambiṭṭu, eḷḷuṇḍe and turmeric-leaf kaḍubu',fig_row('Tambiṭṭu balls, sesame laddus, rolls in turmeric leaves and puffed rice',[(laddu('#c98a3a'),1.8),(laddu('#8a6a4a'),1.8),(leaf('#3a8a3a'),1.6),(plate(),1.6)],['tambiṭṭu','eḷḷuṇḍe','arisina ele kaḍubu','araḷu'],gy=150),[('🟤','Tambiṭṭu','Balls of roasted flour (rice, gram or wheat) with jaggery, cardamom and ghee: made the day before, so nothing need be fried on Pañcamī.'),('⚪','Eḷḷuṇḍe','Sesame and jaggery balls, with puffed rice (<i>araḷu</i>) and roasted gram; offered at the anthill.'),('🍃','On the coast','<b>Arisina eleya kaḍubu</b> (Pātoli in Konkani homes): rice batter with coconut and jaggery steamed in fragrant turmeric leaves, the monsoon treat of Tuḷunāḍu.'),('🥛','Milk','Milk, of course, offered first, and taken home as prasāda for the brothers and the children.')],[('z','Why turmeric leaves?'),('b','They give the steamed rolls a wonderful smell, Zappy. Turmeric is also sacred to the nāgas on the coast.')],'Steamed, roasted, <b>never fried</b>.'),
 reading('tulunadu','TUḶUNĀḌU, NĀGABANA AND KUKKE','The coast’s serpent faith',svg(560,170,'A sacred grove of trees around serpent stones, with a large coloured serpent design drawn on the ground',f'<rect width="560" height="170" fill="#cfe0d8"/>'+'<rect y="140" width="560" height="30" fill="#a8c890"/>'+g(160,150,1.2,grove())+g(420,95,1,mandala())),['<b>Nāgabana.</b> In Dakshina Kannaḍa and Uḍupi nearly every family and village has a <b>nāgabana</b>, a small grove left uncut for the serpents, with stone nāga images under the trees. On Pañcamī milk, tender coconut water, turmeric and flowers are offered there; in many coastal homes the men perform the worship.','<b>Nāgamaṇḍala.</b> The coast’s great serpent ritual, the all-night <b>Nāgamaṇḍala</b>, is held at other seasons: a vast coloured serpent design is drawn on the ground, and performers in trance dance around it till dawn.','<b>Kukke Subrahmaṇya.</b> In the Western Ghāṭs stands <b>Kukke Subrahmaṇya</b>, where Subrahmaṇya protects the serpent king Vāsuki, who took refuge there from Garuḍa. It is Karnataka’s great shrine for serpent vows and rites. See our '+L('/subramanya/','Subrahmaṇya pages')+'.','<b>Why groves matter.</b> The nāgabanas are among the last fragments of old forest on the coast; protecting them protects real snakes, frogs, trees and springs.'],[('z','Why are the groves left wild?'),('b','For the nāgas, Zappy. And as a bonus, they’re little forests the village never cut down.')],'Little forests <b>for the serpents</b>.'),
 cards('india','ACROSS INDIA','Nāgula Chavithi to Manasā',fig_row('An anthill, a cobra image on a wall, a goddess and a grove',[(anthill(),1),(cobra(),1),(devi(sari='#2a6a3a',items=('lotus',)),.7),(tree('#2f6a3a'),.8)],['Nāgula Chavithi','wall nāgas','Manasā','sarpakkāvu'],gy=150),[('🐜','Telugu states','<b>Nāgula Chavithi</b>, in Kārtika, with milk and eggs at anthills; Nāga Pañcamī too in some families.'),('🖼️','North and Nepal','Serpent images drawn with cow-dung or charcoal on walls; pictures of nāgas pasted above doors in Nepal.'),('🐍','Bengal and Assam','<b>Manasā</b>, goddess of snakes, worshipped through the monsoon months.'),('🌳','Kerala','<b>Sarpakkāvu</b> groves in family compounds and the famous Mannārśāla serpent temple; women pray for children and for their brothers.')],[('z','Live cobras anywhere?'),('b','Not any more, Zappy. Courts and wildlife law stopped the catching of snakes for the festival. Good.')],'One fear, <b>many reverences</b>.'),
 reading('kind','BE KIND TO REAL SNAKES','Worship without harm',svg(560,150,'A cobra moving away into the grass while a family watches from a distance',f'<rect width="560" height="150" fill="#cfe0d8"/>'+'<rect y="120" width="560" height="30" fill="#a8c890"/>'+g(420,128,1,cobra())+g(150,130,1,person('#c0392b'))+g(200,130,.9,child())+'<path d="M250 100 h80" stroke="#2a9d6f" stroke-width="3" stroke-dasharray="6 4"/>'),['<b>Snakes do not drink milk.</b> They are reptiles; forcing milk into a captured snake can kill it. The milk of the festival belongs on the stone and the anthill, as an offering.','<b>No snake charmers.</b> Snakes caught for the festival are often defanged, starved and kept in baskets. Catching or keeping them is forbidden under India’s Wildlife (Protection) Act.','<b>Leave them be.</b> The traditional way is the kind one: worship the stone, protect the grove, and leave live snakes alone. If one comes into the house, call a trained rescuer.','<b>The spirit.</b> The festival honours the creature; hurting it in the festival’s name turns the day upside down.'],[('z','Then why pour milk at all?'),('b','On the stone or anthill, as an offering, Zappy. Never into a live snake’s mouth.')],'Honour the snake <b>by leaving it alone</b>.'),
 reading('meaning','WHAT NĀGA PAÑCAMĪ MEANS','Peace with the wild',svg(560,150,'A serpent coiled peacefully around a liṅga, with Viṣṇu resting on Śeṣa in the background',f'<rect width="560" height="150" fill="#e3eaf3"/>'+g(170,140,1.1,linga())+g(170,110,.7,cobra())+g(400,130,.8,sheshashayi())),['<b>From fear to respect.</b> The most dangerous creature of the village is worshipped, not killed. Many read the festival as India’s old way of living with the wild. (Interpretation.)','<b>The serpent in the gods.</b> Śeṣa is Viṣṇu’s couch, Vāsuki is Śiva’s ornament and the churning rope, Subrahmaṇya is the serpents’ protector: the nāga is everywhere sacred, never merely an enemy.','<b>Family.</b> In Karnataka the day belongs to sisters, brothers and daughters coming home: the festival of the serpent is also the festival of the family’s safety.','<b>Restraint.</b> No digging, no frying, no harm: one day a year to walk lightly on the earth.'],[('z','If I could do one thing for Nāga Pañcamī?'),('b','Say the nine names, Zappy, and leave one patch of earth undug for whatever lives there.')],'Respect <b>what we fear</b>.'),
 end(i,['<b>When.</b> Śrāvaṇa Śukla Pañcamī, in the monsoon.','<b>Stories.</b> Kadru’s curse; Takṣaka and Parīkṣit; Āstīka stops the sacrifice; Kāliya.','<b>Verse.</b> The nine serpents: Ananta to Kāliya.','<b>Karnataka.</b> Milk on stones and anthills, sisters and brothers, tambiṭṭu.','<b>Coast.</b> Nāgabanas, Nāgamaṇḍala, Kukke Subrahmaṇya.'],'Previous: '+L('/festivals/rama-navami/','Rāma Navamī')+'. Next: '+L('/festivals/varamahalakshmi/','Varamahālakṣmī Vrata')+'.','Nāga Pañcamī: the serpents’ fifth day'),
 sources([('Stories:','Mahābhārata, Ādi Parvan, Āstīka Parvan (Kadru and Vinatā, Parīkṣit and Takṣaka, Janamejaya’s sarpa-satra, Āstīka); Bhāgavata Purāṇa 10.16 (Kāliya).'),('Customs and verse:','Wikipedia, “Nag Panchami” (date, Āstīka tradition, farmer’s tale, Karnataka girls’ threads and serpent designs, Kerala, Bengal, nine nāga names); Nava Nāga Stotra from shlokam.org and sanskritdocuments.org; Karnataka and Tuḷunāḍu customs as summarised in our earlier guide.')],'the link of Āstīka’s success to this exact day (tradition); tani ereyuvudu and other village customs (vary by district); the farmer’s tale (oral, many versions); Kukke legend details (temple tradition).','Mahābhārata chapter numbers vary between editions.')]
build(i,'MONSOON · SERPENT STONES · SISTERS AND BROTHERS',COV,'Milk on the serpent stone','Why the <b>serpents</b> are worshipped in the rains, the <b>Mahābhārata</b> stories behind the day, the <b>nine-nāga</b> verse, Karnataka’s sisters and brothers, the <b>nāgabanas</b> of the coast, and kindness to real snakes.','Nāga Pañcamī explained: Śrāvaṇa Śukla Pañcamī, Kadru and Vinatā, Takṣaka and Parīkṣit, Āstīka stopping Janamejaya’s snake sacrifice, Kṛṣṇa and Kāliya, the Nava Nāga Stotra, Karnataka’s Nāgara Pañcamī with milk on serpent stones, tambiṭṭu, nāgabanas, Kukke Subrahmaṇya and kindness to snakes.',pp)
print('naga ok',len(pp)+2)
